pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    C c;
    bytes4 IERC1155_ID = type(IERC1155Probe).interfaceId;
    bytes4 IERC1155_METADATA_ID = type(IERC1155MetadataURIProbe).interfaceId;

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(uint256 selectorSeed) public {
        bytes4 probe = bytes4(selectorSeed);
        bool expected = probe == IERC1155_ID || probe == IERC1155_METADATA_ID || probe == type(IERC165Probe).interfaceId;
        bool actual = c.supportsInterface(probe);
        assertTrue(actual == expected, "supportsInterface must report IERC1155 and IERC1155MetadataURI as supported");
    }
}

