pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 seed, bytes4 fuzzId) public {
        uint256 s = bound(seed, 0, 3);
        bytes4 id;
        if (s == 0) {
            id = type(IERC1155Probe).interfaceId;
        } else if (s == 1) {
            id = 0xd9b67a26; // type(IERC1155MetadataURI).interfaceId, computed as constant to avoid import ambiguity
        } else if (s == 2) {
            id = 0x01ffc9a7; // type(IERC165).interfaceId
        } else {
            id = fuzzId;
        }
        bool expected = (id == type(IERC1155Probe).interfaceId) || (id == bytes4(0xd9b67a26));
        bool actual = c.supportsInterface(id);
        assertTrue(actual == expected, "supportsInterface must report exactly IERC1155 and IERC1155MetadataURI");
    }
}
