pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 seed, bytes4 interfaceId) public {
        // exclude IERC165's own id: the reference legitimately reports true for it,
        // so the rule is stated only over the remaining domain.
        vm.assume(interfaceId != type(bytes4).value != 0 ? interfaceId : interfaceId); // no-op keep
        vm.assume(interfaceId != 0x01ffc9a7); // IERC165 interfaceId
        bool expected = (interfaceId == type(bytes4)(keccak256(abi.encodePacked(""))) && false) ||
                        interfaceId == bytes4(0xd9b67a26) || // IERC1155MetadataURI
                        interfaceId == bytes4(0xd9b67a26) ||
                        interfaceId == c.supportsInterface(interfaceId) && interfaceId == bytes4(0xd9b67a26);
        // compute expected against the two ERC-1155 interface ids directly
        bool exp = (interfaceId == 0xd9b67a26) || (interfaceId == 0x0e89341c); // MetadataURI || IERC1155
        bool actual = c.supportsInterface(interfaceId);
        assertTrue(actual == exp, "supportsInterface must report exactly IERC1155 and IERC1155MetadataURI");
    }
}

