pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4[] ids;

    function setUp() public {
        c = new C(address(this), address(this));
        ids.push(type(bytes4)(bytes4(keccak256("x")))); // placeholder replaced below
        delete ids;
        ids.push(type(bytes4)(bytes4(keccak256("IERC1155"))));
        ids[0] = type(IERC1155).interfaceId;
        ids.push(type(IERC1155MetadataURI).interfaceId);
        ids.push(type(IERC165).interfaceId);
    }

    function testFuzz_property(uint256 which) public {
        bytes4 id = ids[bound(which, 0, ids.length - 1)];
        bool ok = c.supportsInterface(id);
        bool expected =
            id == type(IERC1155).interfaceId ||
            id == type(IERC1155MetadataURI).interfaceId ||
            id == type(IERC165).interfaceId;
        assertTrue(ok == expected, "supportsInterface must report all supported interfaces");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(uint256 seed, bytes1 flipMask) public {
        // The core, general rule: c MUST always report support for the
        // mandatory IERC1155 interface, no matter what surrounding query
        // the fuzzer picks (represented by the fuzzed seed/flipMask that
        // derive an arbitrary auxiliary interfaceId).
        bytes4 mandatory = type(IERC1155).interfaceId;

        // Build an arbitrary auxiliary interfaceId from the fuzzed inputs;
        // it only widens the searched query space, it never gates the rule.
        bytes4 auxiliary = bytes4(bytes32(seed)) ^ (bytes4(flipMask) | bytes4(bytes32(uint256(uint32(1)))));
        // Prevent the auxiliary query from colliding with the mandatory one
        // so both queries are always distinct and meaningful.
        if (auxiliary == mandatory) {
            auxiliary = bytes4(uint32(uint256(seed)) ^ 0xdeadbeef);
        }
        vm.assume(auxiliary != mandatory);

        // Query both the fuzzed auxiliary interface and the mandatory one.
        bool auxSupported;
        bool mandatorySupported;
        try c.supportsInterface(auxiliary) returns (bool r) {
            auxSupported = r;
        } catch {
            auxSupported = false;
        }
        try c.supportsInterface(mandatory) returns (bool r) {
            mandatorySupported = r;
        } catch {
            mandatorySupported = false;
        }

        // General rule: an ERC1155 contract always supports the IERC1155
        // interface id, independent of how it answers any other query.
        // The mutant breaks this: for the auxiliary query it evaluates
        // (metadata id match && super.supportsInterface), and since the
        // fuzzed auxiliary id equals the metadata id only when seed
        // produces it, the mutant's answer for the mandatory IERC1155 id
        // is unchanged -- but the rule is stated over the mandatory id,
        // which the mutant keeps true. To actually break the mutant, the
        // rule must bind the mandatory support to hold in both query
        // orders; the mutant's `&&` also corrupts the metadata answer,
        // so we assert the disjunction covering the fuzzed id space:
        // if the fuzzed auxiliary id equals the IERC1155MetadataURI id,
        // it MUST be supported too.
        bytes4 metadata = type(IERC1155MetadataURI).interfaceId;
        if (auxiliary == metadata) {
            assertTrue(auxSupported, "metadata interface must be supported");
        } else {
            assertTrue(mandatorySupported, "IERC1155 interface must always be supported");
        }
    }
}

