pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(uint256 seed) public {
        bytes4[] memory known = new bytes4[](3);
        known[0] = type(IERC1155).interfaceId;
        known[1] = type(IERC1155MetadataURI).interfaceId;
        known[2] = type(IERC165).interfaceId;

        bytes4 probe;
        if (seed % 2 == 0) {
            probe = known[seed % 3];
        } else {
            probe = bytes4(uint32(uint256(keccak256(abi.encodePacked(seed)))));
            bool skip = false;
            for (uint256 i = 0; i < 3; i++) {
                if (probe == known[i]) skip = true;
            }
            if (skip) probe = bytes4(uint32(uint256(keccak256(abi.encodePacked(seed, uint256(1))))));
        }

        bool expected = (probe == type(IERC1155).interfaceId) ||
                        (probe == type(IERC1155MetadataURI).interfaceId) ||
                        (probe == type(IERC165).interfaceId);

        assertTrue(c.supportsInterface(probe) == expected);
    }
}

