pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes4 constant IERC165_ID = 0x01ffc9a7; // bytes4(keccak256("supportsInterface(bytes4)"))

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(bytes4 probe) public {
        // Rule: for every probe, whenever probe is the ERC165 interface id,
        // c must report support for it (ERC165 self-declaration via super.supportsInterface).
        if (probe == IERC165_ID) {
            bool ok = c.supportsInterface(probe);
            assertTrue(ok, "ERC165 interface id must be supported");
        } else {
            // for non-ERC165 ids the call must simply not revert; read behavior
            bool ok;
            try c.supportsInterface(probe) returns (bool) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(ok, "supportsInterface must not revert");
        }
    }
}

