pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Neuron neuron;

    function setUp() public {
        c = new C(address(this), address(this));
        neuron = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(neuron));
        // the game-item contract pays for purchases on behalf of buyers
        neuron.addSpender(address(c));
        // create one free item (price 0) with a positive daily allowance
        c.createGameItem("item", "uri", false, true, 0, 0, 100);
    }

    function testFuzz_property(address actor, uint256 tokenId, uint256 quantity) public {
        // keep the actor an admissible EOA recipient (non-zero, no code => no receiver hook)
        actor = address(uint160(bound(uint160(actor), 1, type(uint160).max)));
        vm.assume(actor.code.length == 0);
        tokenId = bound(tokenId, 0, c.uniqueTokensOutstanding() - 1);
        quantity = bound(quantity, 1, 100); // within the item's daily allowance

        vm.prank(actor);
        c.mint(tokenId, quantity);

        // GENERAL RULE: balanceOf reports the stored (minted) balance of the account
        assertTrue(c.balanceOf(actor, tokenId) == quantity);
    }
}
